import os, django, csv, base64

os.environ.setdefault('DJANGO_SETTINGS_MODULE', 'backend.settings')
django.setup()
from accounting.models import MasterHierarchyRaw

b64_data = ''
raw_bytes = base64.b64decode(b64_data)
content = raw_bytes.decode('utf-8-sig', errors='ignore').replace('\x00', '')

# Also write to /app/ledgers.csv for record
try:
    with open('/app/ledgers.csv', 'wb') as f:
        f.write(raw_bytes)
except Exception as e:
    pass

lines = [line for line in content.splitlines() if line.strip()]
reader = csv.DictReader(lines)
MasterHierarchyRaw.objects.all().delete()

def clean(val):
    if not val: return None
    s = str(val).strip()
    return None if s == '' or s == '-' or s.lower() in ('null', 'none') else s

instances = []
for row in reader:
    btype = clean(row.get('type_of_business_1') or row.get('Type of Business'))
    if not btype: continue
    instances.append(MasterHierarchyRaw(
        type_of_business_1=btype,
        financial_reporting_1=clean(row.get('financial_reporting_1') or row.get('Financial Reporting')),
        major_group_1=clean(row.get('major_group_1') or row.get('Major Group')),
        group_1=clean(row.get('group_1') or row.get('Group')),
        sub_group_1_1=clean(row.get('sub_group_1_1') or row.get('Sub-group 1')),
        sub_group_2_1=clean(row.get('sub_group_2_1') or row.get('Sub-group 2')),
        sub_group_3_1=clean(row.get('sub_group_3_1') or row.get('Sub-group 3')),
        ledger_1=clean(row.get('ledger_1') or row.get('Ledgers')),
        code=clean(row.get('code') or row.get('Code'))
    ))

MasterHierarchyRaw.objects.bulk_create(instances, batch_size=1000)
types = sorted(list(set(MasterHierarchyRaw.objects.values_list('type_of_business_1', flat=True))))
print(f'\n>>> SUCCESSFULLY IMPORTED {len(instances)} UPDATED ROWS FROM LEDGERS.CSV! Business Types in DB: {types} <<<')
